 acknowledgeScheduled(id:string,sourceSessionId=this.sessionId):void{const source=sourceSessionId===this.sessionId?this:[...this.activeInvocations.values()].map(item=>item.child).find(child=>child.getSessionId()===sourceSessionId);source?.pending.delete(id);}
 recordCancellation(id:string):void{this.pending.delete(id);this.trace.push({kind:'cancelled',message:`Cancelled scheduled send ${id}.`});}
 private result():SimulationResult{return{snapshot:this.snapshot(),effects:[...this.effects]};}
 private snapshot():SimulationSnapshot{return{active:this.completedFinalStateId?[this.completedFinalStateId]:this.atomicActive(),trace:[...this.trace],completed:this.sessionCompleted,completionOutput:this.cloneValue(this.completionOutput),step:this.step,pending:[...this.pending].map(([id,item])=>({id,...item})),dataModel:this.cloneData(this.dataModel),logs:[...this.logs]};}
 private atomicActive():string[]{return[...this.active].filter(id=>{const s=this.byId.get(id);return s&&!s.children.some(c=>this.active.has(c.id));}).sort((a,b)=>this.documentOrder(a)-this.documentOrder(b));}
 private documentOrder(id:string):number{return this.stateOrder.get(id)??Number.MAX_SAFE_INTEGER;}
 private entryOrder(ids:string[]):string[]{return[...new Set(ids)].sort((a,b)=>this.ancestors(a).length-this.ancestors(b).length||this.documentOrder(a)-this.documentOrder(b));}
 private exitOrder(ids:string[]):string[]{return[...new Set(ids)].sort((a,b)=>this.ancestors(b).length-this.ancestors(a).length||this.documentOrder(b)-this.documentOrder(a));}
 private enteredStatesSince(before:Set<string>):string[]{return this.entryOrder([...this.active].filter(id=>!before.has(id)));}
 private enter(id:string):void{const target=this.byId.get(id);if(!target)return;if(target.kind==='history'){this.enterHistory(target);return;}const lineage=this.ancestors(id).reverse();for(const ancestor of lineage.slice(0,-1))if(ancestor.kind!=='history')this.active.add(ancestor.id);this.enterState(target);}
 private enterState(state:StateNode):void{if(state.kind==='history'){this.enterHistory(state);return;}this.active.add(state.id);this.initializeStateDataIfNeeded(state);this.pendingEntryActions.push(state.id);this.markStateForInvocation(state.id);if(state.kind==='parallel')state.children.filter(child=>child.kind!=='history').forEach(child=>this.enterState(child));else if(state.children.some(child=>child.kind!=='history')){const initial=state.initial||state.children.find(child=>child.kind!=='history')?.id;if(initial)this.enterInitialConfiguration(state,initial);}}
 private enterInitialConfiguration(owner:StateNode|undefined,fallbackTarget:string):void{if(owner)this.flushPendingEntryActions();const transition=this.initialTransitionElement(owner);const targetValue=getAttribute(transition??({attributes:[]} as unknown as XmlSourceElement),'target')?.value;const targets=(targetValue??fallbackTarget).split(/\s+/).filter(Boolean);if(transition){const label=owner?`state ${owner.id}`:'SCXML root';this.trace.push({kind:'transition',targets,message:`Executing explicit initial transition for ${label} -> ${targets.join(' ')}.`});this.executeActions(transition);}this.enterTargetSet(targets);}
 private initialTransitionElement(owner:StateNode|undefined):XmlSourceElement|undefined{const scope=owner?findElementById(this.sourceDocument,new Set(['state']),owner.id):this.sourceDocument.roots.find(element=>element.localName==='scxml');const initial=scope?directChildren(scope,'initial')[0]:undefined;return initial?directChildren(initial,'transition')[0]:undefined;}
 private enterHistory(history:StateNode):void{const owner=this.parent.get(history.id);if(!owner){this.queueExecutionError(`History ${history.id} has no owning state.`,{historyId:history.id});return;}if(!this.active.has(owner.id)){this.active.add(owner.id);this.pendingEntryActions.push(owner.id);}const stored=this.historyValues.get(history.id);if(stored?.length){this.trace.push({kind:'transition',message:`Restored ${history.historyType==='deep'?'deep':'shallow'} history ${history.id}: ${stored.join(', ')}`});this.enterTargetSet(stored);return;}const fallback=history.transitions[0];if(!fallback?.targets.length){this.queueExecutionError(`History ${history.id} has no stored configuration or default target.`,{historyId:history.id});return;}this.trace.push({kind:'transition',message:`History ${history.id} has no stored configuration; using default target ${fallback.targets.join(' ')}`});this.executeTransitionActions(history.id,0);this.enterTargetSet(fallback.targets);}
 private recordHistoryForExit(domain:StateNode|'scxml'):void{const exitingOwners=[...this.byId.values()].filter(state=>state.kind!=='history'&&this.active.has(state.id)&&(domain==='scxml'||state.id===domain.id||this.isDescendant(state.id,domain.id)));for(const owner of exitingOwners){for(const history of owner.children.filter(child=>child.kind==='history')){const deep=history.historyType==='deep';const recorded=deep?this.atomicActive().filter(id=>this.isDescendant(id,owner.id)):owner.children.filter(child=>child.kind!=='history'&&this.active.has(child.id)).map(child=>child.id);if(recorded.length){this.historyValues.set(history.id,[...recorded]);this.trace.push({kind:'transition',message:`Recorded ${deep?'deep':'shallow'} history ${history.id}: ${recorded.join(', ')}`});}}}}
 private exit(id:string):void{for(const a of[...this.active])if(a===id||this.isDescendant(a,id))this.active.delete(a);}
 private isDescendant(id:string,ancestor:string):boolean{let p=this.parent.get(id);while(p){if(p.id===ancestor)return true;p=this.parent.get(p.id);}return false;}
