 private matches(d:string|undefined,e:string):boolean{return Boolean(d?.split(/\s+/).filter(Boolean).some(x=>x==='*'||x.endsWith('.*')?(e===x.slice(0,-2)||e.startsWith(x.slice(0,-1))):(e===x||e.startsWith(x+'.'))));}
 private conditionEnabled(c:string|undefined):boolean{if(!c||!c.trim())return true;try{const enabled=Boolean(this.evaluate(c));this.trace.push({kind:'transition',message:`Condition ${c}: ${enabled}`});return enabled;}catch(error){this.queueExecutionError(`Condition ${c}: ${this.errorMessage(error)}`,{expression:c});return false;}}
 private candidates(event?:string):TransitionCandidate[]{const found:TransitionCandidate[]=[];const seen=new Set<string>();const eligibility=new Map<string,boolean>();for(const leaf of this.atomicActive().sort((a,b)=>(this.stateOrder.get(a)??0)-(this.stateOrder.get(b)??0))){for(const source of this.ancestors(leaf)){const index=source.transitions.findIndex((transition,transitionIndex)=>{if(!(event?this.matches(transition.event,event):!transition.event))return false;const key=`${source.id}:${transitionIndex}`;let enabled=eligibility.get(key);if(enabled===undefined){enabled=this.conditionEnabled(transition.cond);eligibility.set(key,enabled);}return enabled;});if(index>=0){const key=`${source.id}:${index}`;if(!seen.has(key)){seen.add(key);const transition=source.transitions[index];found.push({source,transition,index,depth:this.ancestors(source.id).length,sourceOrder:this.documentOrder(source.id),exitSet:this.transitionExitSet(source,transition)});}break;}}}return found;}
 private transitionExitSet(source:StateNode,transition:Transition):Set<string>{if(!transition.targets.length)return new Set();const domain=this.domain(source,transition.targets,transition.type);if(!domain)return new Set();return new Set([...this.active].filter(id=>domain==='scxml'||(transition.type==='internal'&&domain.id===source.id?this.isDescendant(id,domain.id):id===domain.id||this.isDescendant(id,domain.id))));}
