 private executeCancel(action:XmlSourceElement):void{try{const literal=getAttribute(action,'sendid')?.value,expression=getAttribute(action,'sendidexpr')?.value;const id=literal??(expression!==undefined?this.evaluate(expression):undefined);if(typeof id!=='string'||!id.trim())throw new Error('cancel send ID evaluated to an empty or non-string value');const normalized=id.trim();if(this.pending.has(normalized)){this.pending.delete(normalized);this.effects.push({kind:'cancel',id:normalized,sourceSessionId:this.sessionId});this.trace.push({kind:'cancelled',message:`Requested cancellation of scheduled send ${normalized}.`});}else this.trace.push({kind:'cancelled',message:`Cancel ignored unknown or already-delivered send ${normalized}.`});}catch(error){this.queueExecutionError(`Cancel: ${this.errorMessage(error)}`,{action:'cancel'});}}
 private stringChoice(action:XmlSourceElement,literalName:string,expressionName:string,required:boolean):string|undefined{const literal=getAttribute(action,literalName)?.value,expression=getAttribute(action,expressionName)?.value;const value=literal!==undefined?literal:expression!==undefined?this.evaluate(expression):undefined;if(value===undefined||value===null||String(value).trim()===''){if(required)throw new Error(`${literalName} evaluated to an empty value`);return undefined;}return String(value).trim();}
 private delayFromExpression(value:unknown):number{if(typeof value==='number'){if(!Number.isFinite(value)||value<0)throw new Error('delayexpr must evaluate to a non-negative number or delay string');return value;}if(typeof value==='string'){const parsed=this.delayMs(value,true);return parsed;}throw new Error('delayexpr must evaluate to a non-negative number or delay string');}
 private sendData(action:XmlSourceElement):unknown{const content=directChildren(action,'content')[0],params=directChildren(action,'param');if(content){const expr=getAttribute(content,'expr')?.value;if(expr!==undefined)return this.cloneValue(this.evaluate(expr));const raw=this.text.slice(content.openEnd,content.closeStart).trim();return raw||null;}const data:Record<string,unknown>={};const namelist=(getAttribute(action,'namelist')?.value||'').split(/\s+/).filter(Boolean);for(const name of namelist)data[name]=this.cloneValue(this.readLocation(name));for(const param of params){const name=getAttribute(param,'name')?.value;if(!name)continue;const expr=getAttribute(param,'expr')?.value,location=getAttribute(param,'location')?.value;data[name]=this.cloneValue(expr!==undefined?this.evaluate(expr):location?this.readLocation(location):undefined);}return data;}

