 private executeRootScripts():void{const root=this.sourceDocument.roots.find(item=>item.localName==='scxml');if(!root)return;for(const script of directChildren(root,'script')){this.trace.push({kind:'transition',message:'Executing root script before initial-state entry.'});this.executeScript(script);}}
 private initializeDataModels():void{const root=this.sourceDocument.roots.find(item=>item.localName==='scxml');if(!root)return;this.initializeDataScope(root,'scxml');if(this.binding==='early'){for(const element of this.sourceDocument.elements){if(!['state','parallel'].includes(element.localName))continue;const id=getAttribute(element,'id')?.value;if(id)this.initializeDataScope(element,id);}}}
 private initializeStateDataIfNeeded(state:StateNode):void{if(this.binding!=='late'||!['state','parallel'].includes(state.kind))return;const element=findElementById(this.sourceDocument,new Set(['state','parallel']),state.id);if(element)this.initializeDataScope(element,state.id);}
 private initializeDataScope(scope:XmlSourceElement,scopeId:string):void{if(this.initializedDataScopes.has(scopeId))return;this.initializedDataScopes.add(scopeId);const model=directChildren(scope,'datamodel')[0];if(!model)return;for(const data of directChildren(model,'data'))this.initializeDataDeclaration(data,scopeId);}
 private initializeDataDeclaration(data:XmlSourceElement,scopeId:string):void{const id=getAttribute(data,'id')?.value;if(!id)return;const expr=getAttribute(data,'expr')?.value,src=getAttribute(data,'src')?.value;try{let value:unknown;if(expr!==undefined)value=this.evaluate(expr);else if(src!==undefined){const resource=this.resolveResource(data,src,'data');if(resource===undefined)throw new Error(`external data source ${src} could not be resolved`);value=this.parseExternalData(resource);}else value=this.inlineDataValue(data);this.dataModel[id]=value;this.trace.push({kind:'transition',message:`Initialized data ${id} in ${scopeId}: ${this.formatValue(value)}`});}catch(error){this.dataModel[id]=undefined;const message=this.errorMessage(error);if(src!==undefined&&message.includes('could not be resolved'))this.queueCommunicationError(`Data ${id} in ${scopeId}: ${message}`,{dataId:id,scopeId,src});else this.queueExecutionError(`Data ${id} in ${scopeId}: ${message}`,{dataId:id,scopeId,src});}}
 private inlineDataValue(data:XmlSourceElement):unknown{if(data.selfClosing)return null;const raw=this.text.slice(data.openEnd,data.closeStart).trim();if(!raw)return null;if(directChildren(data).length)return raw;const cdata=/^<!\[CDATA\[([\s\S]*)\]\]>$/.exec(raw);return this.evaluate(cdata?cdata[1]:raw);}

 private executeIf(action:XmlSourceElement):void{const branches:XmlSourceElement[][]=[[]];const conditions:Array<string|undefined>=[getAttribute(action,'cond')?.value];for(const child of directChildren(action)){if(child.localName==='elseif'){branches.push([]);conditions.push(getAttribute(child,'cond')?.value);continue;}if(child.localName==='else'){branches.push([]);conditions.push(undefined);continue;}branches[branches.length-1].push(child);}let selected=-1;for(let index=0;index<conditions.length;index++){const condition=conditions[index];if(condition===undefined){selected=index;break;}try{const enabled=Boolean(this.evaluate(condition));this.trace.push({kind:'transition',message:`If condition ${condition}: ${enabled}`});if(enabled){selected=index;break;}}catch(error){this.queueExecutionError(`If condition ${condition}: ${this.errorMessage(error)}`,{expression:condition});return;}}if(selected<0){this.trace.push({kind:'transition',message:'If: no branch selected.'});return;}this.trace.push({kind:'transition',message:`If: selected ${selected===0?'if':conditions[selected]===undefined?'else':`elseif ${selected}`} branch.`});this.executeActionList(branches[selected]);}
 private executeActionList(actions:XmlSourceElement[]):boolean{for(const action of actions)if(!this.executeAction(action))return false;return true;}
 private executeAction(action:XmlSourceElement):boolean{const errorsBefore=this.platformErrorSequence;if(action.localName==='send')this.executeSend(action);else if(action.localName==='cancel')this.executeCancel(action);else if(action.localName==='assign')this.executeAssign(action);else if(action.localName==='log')this.executeLog(action);else if(action.localName==='if')this.executeIf(action);else if(action.localName==='foreach')return this.executeForeach(action);else if(action.localName==='script')this.executeScript(action);else if(action.localName==='raise'){const event=getAttribute(action,'event')?.value;if(event){this.internalQueue.push(this.createEvent(event,'internal'));this.trace.push({kind:'scheduled',event,message:`Raised internal event ${event}.`});}}return this.platformErrorSequence===errorsBefore;}
 private effectiveBaseUri(element:XmlSourceElement):string{const chain:XmlSourceElement[]=[];let current:XmlSourceElement|undefined=element;while(current){chain.unshift(current);current=current.parent;}let base=this.documentUri;for(const item of chain){const value=getAttribute(item,'xml:base')?.value;if(value)base=new URL(value,base).toString();}return base;}
 private resolveUri(element:XmlSourceElement,reference:string):string{try{return new URL(reference,this.effectiveBaseUri(element)).toString();}catch{throw new Error(`invalid resource URI ${reference}`);}}
 private resolveResource(element:XmlSourceElement,reference:string,kind:ScxmlResourceKind):string|undefined{const uri=this.resolveUri(element,reference);const value=this.options.resolveResource?.(uri,kind)??(kind==='invoke'?this.options.resolveInvoke?.(reference):kind==='script'?this.options.resolveScript?.(reference):undefined);this.trace.push({kind:value===undefined?'error':'transition',message:value===undefined?`Unable to resolve ${kind} resource ${uri}.`:`Resolved ${kind} resource ${uri}.`});return value;}
 private parseExternalData(source:string):unknown{const value=source.trim();if(!value)return null;try{return this.evaluate(value);}catch{return value;}}
 private executeScript(action:XmlSourceElement):void{const src=getAttribute(action,'src')?.value;try{const source=src!==undefined?this.resolveResource(action,src,'script'):this.scriptText(action);if(source===undefined)throw new Error(`script source ${src} could not be resolved`);const program:any=acorn.parse(source,{ecmaVersion:2020,allowReturnOutsideFunction:true});this.executeStatements(program.body);this.trace.push({kind:'transition',message:src?`Executed external script ${src}.`:'Executed inline script.'});}catch(error){const message=this.errorMessage(error);if(src!==undefined&&message.includes('could not be resolved'))this.queueCommunicationError(`Script: ${message}`,{src});else this.queueExecutionError(`Script: ${message}`,{src});}}
