 private executeStatements(statements:any[],loop=false):{kind:'normal'|'break'|'continue'|'return';value?:unknown}{let result:unknown;for(const statement of statements){const outcome=this.executeStatement(statement,loop);if(outcome.kind!=='normal')return outcome;result=outcome.value;}return{kind:'normal',value:result};}
 private executeStatement(statement:any,loop=false):{kind:'normal'|'break'|'continue'|'return';value?:unknown}{if(statement.type==='EmptyStatement')return{kind:'normal'};if(statement.type==='ExpressionStatement')return{kind:'normal',value:this.executeScriptExpression(statement.expression)};if(statement.type==='VariableDeclaration'){this.executeVariableDeclaration(statement);return{kind:'normal'};}if(statement.type==='BlockStatement')return this.executeStatements(statement.body,loop);if(statement.type==='IfStatement'){const branch=this.evaluateNode(statement.test)?statement.consequent:statement.alternate;return branch?this.executeStatement(branch,loop):{kind:'normal'};}if(statement.type==='BreakStatement'){if(!loop||statement.label)throw new Error('break is supported only inside an unlabeled loop');return{kind:'break'};}if(statement.type==='ContinueStatement'){if(!loop||statement.label)throw new Error('continue is supported only inside an unlabeled loop');return{kind:'continue'};}if(statement.type==='ReturnStatement')return{kind:'return',value:statement.argument?this.evaluateNode(statement.argument):undefined};if(statement.type==='WhileStatement')return this.executeWhileStatement(statement,false);if(statement.type==='DoWhileStatement')return this.executeWhileStatement(statement,true);if(statement.type==='ForStatement')return this.executeForStatement(statement);if(statement.type==='ForOfStatement')return this.executeForOfStatement(statement);if(statement.type==='ForInStatement')return this.executeForInStatement(statement);if(statement.type==='SwitchStatement')return this.executeSwitchStatement(statement,loop);if(statement.type==='ThrowStatement')throw this.scriptThrownValue(statement.argument);if(statement.type==='TryStatement')return this.executeTryStatement(statement,loop);throw new Error(`Unsupported script statement ${statement.type}`);}
