 private locationReference(location:string,create:boolean):{object:any;key:string|number}{const source=location.replace(/&gt;/g,'>').replace(/&lt;/g,'<').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&apos;/g,"'").trim();if(!source)throw new Error('Location is empty');const node:any=acorn.parseExpressionAt(source,0,{ecmaVersion:2020});if(source.slice(node.end).trim())throw new Error('Unexpected text after location');const parts:Array<string|number>=[];let current=node;while(current?.type==='MemberExpression'&&!current.optional){const key=current.computed?this.evaluateNode(current.property):current.property.name;if(typeof key!=='string'&&typeof key!=='number')throw new Error('Computed location key must be a string or number');parts.unshift(key);current=current.object;}if(current?.type!=='Identifier')throw new Error('Location must start with a data-model variable');parts.unshift(current.name);if(parts.length===1)return{object:this.dataModel,key:String(parts[0])};let object:any=this.dataModel[String(parts[0])];if((object===undefined||object===null)&&create)object=this.dataModel[String(parts[0])]=typeof parts[1]==='number'?[]:{};if(object===undefined||object===null||typeof object!=='object')throw new Error(`Location root ${String(parts[0])} is not an object`);for(let index=1;index<parts.length-1;index++){const key=parts[index];if((object[key]===undefined||object[key]===null)&&create)object[key]=typeof parts[index+1]==='number'?[]:{};if(object[key]===undefined||object[key]===null||typeof object[key]!=='object')throw new Error(`Location segment ${String(key)} is not an object`);object=object[key];}return{object,key:parts[parts.length-1]};}
